package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"unicode"
	"unicode/utf8"
)

type CreateInput struct {
	Title string `json:"title"`
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	if !scanner.Scan() {
		fmt.Println("Missing input")
		return
	}
	var input CreateInput
	if err := json.Unmarshal(scanner.Bytes(), &input); err != nil {
		fmt.Println("Invalid JSON input")
		return
	}
	title := input.Title
	if title == "" || strings.TrimSpace(title) != title || utf8.RuneCountInString(title) > 120 || strings.IndexFunc(title, unicode.IsControl) >= 0 {
		fmt.Println("Invalid title")
		return
	}
	fmt.Println("Accepted:", title)
}

package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
)

func list(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode([]string{}); err != nil {
		return
	}
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /tasks", list)
	req := httptest.NewRequest("GET", "/tasks", nil)
	res := httptest.NewRecorder()
	mux.ServeHTTP(res, req)
	fmt.Println(res.Code)
	fmt.Print(res.Body.String())
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
)

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /tasks", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprintln(w, "[]")
	})
	cases := []struct {
		method string
		want int
	}{
		{"GET", 200},
		{"POST", 405},
	}
	for _, tc := range cases {
		req := httptest.NewRequest(tc.method, "/tasks", nil)
		res := httptest.NewRecorder()
		mux.ServeHTTP(res, req)
		fmt.Println(tc.method, res.Code, res.Code == tc.want)
	}
}
